<?php require_once __DIR__.'/../../includes/functions.php';$u=require_auth();$d=request_json();verify_csrf($d['_csrf']??'');$f=owned_file((int)($d['id']??0),$u['id']);$name=trim($d['name']??'');if($name===''||strlen($name)>255)json_response(['error'=>'Invalid name.'],422);db()->prepare('UPDATE files SET file_name=?,file_extension=?,updated_at=NOW() WHERE id=? AND user_id=?')->execute([$name,ext_of($name),$f['id'],$u['id']]);log_activity($u['id'],'Rename',$f['id'],$f['folder_id'],'Renamed to '.$name);json_response(['ok'=>1]);